+	if err != nil {
+		return fmt.Errorf("create migrated full/current commit: %w", err)
+	}
+
+	if err := p.repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
+		return fmt.Errorf("update %s: %w", refName, err)
+	}
+
+	p.pending = nil
+	return nil
+}
